const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point(11.184384, 35.114837);
    const aoi = point.buffer(5000); // 5 km buffer around the point

    const date2022 = ee.Date('2022-02-14');
    const date2019 = ee.Date('2019-02-06');

    // Function to mask clouds in Sentinel-2 images
    function maskS2clouds(image) {
        const qa = image.select('QA60');
        // Bits 10 and 11 are clouds and cirrus, respectively.
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        // Both flags should be set to zero, indicating clear conditions.
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
            .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000); // Scale data
    }

    // Function to calculate water pixels
    function getWaterPixels(image) {
        // NDWI = (Green - NIR) / (Green + NIR)
        // For Sentinel-2: (B3 - B8) / (B3 + B8)
        const ndwi = image.normalizedDifference(['B3', 'B8']).rename('ndwi');
        // Water is generally considered to have NDWI > 0
        const waterMask = ndwi.gt(0);
        return waterMask.rename('water');
    }

    // Function to process a single date
    async function calculateWaterExtent(date, aoi) {
        const dateRange = date.getRange('day');
        let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(aoi)
            .filterDate(dateRange)
            .sort('CLOUDY_PIXEL_PERCENTAGE');

        if (collection.size().getInfo() === 0) {
            return {
                pixels: null,
                count: 0
            }; // Indicates no image found
        }

        const image = ee.Image(collection.first());
        const cloudMasked = maskS2clouds(image);
        const waterImage = getWaterPixels(cloudMasked);

        const stats = waterImage.reduceRegion({
            reducer: ee.Reducer.sum().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: aoi,
            scale: 30, // Using a moderate scale
            maxPixels: 1e9
        });

        // Use ee.Number to handle potential nulls from the reducer safely
        const waterPixels = ee.Number(stats.get('water_sum'));
        const totalPixels = ee.Number(stats.get('water_count'));

        return {
            pixels: waterPixels.getInfo(),
            count: totalPixels.getInfo()
        };
    }

    // 2. Data Acquisition & Processing
    const result2022 = await calculateWaterExtent(date2022, aoi);
    const result2019 = await calculateWaterExtent(date2019, aoi);

    // 3. Validation & Final Answer
    if (result2022.count === null || result2019.count === null) {
        console.log('Error: Could not retrieve images for one or both dates.');
        console.log('2022 Image Found:', result2022.count !== null);
        console.log('2019 Image Found:', result2019.count !== null);
        console.log('A');
        return;
    }

    if (result2022.count === 0 || result2019.count === 0) {
        console.log('Error: No valid (cloud-free) pixels found in the area of interest for one or both dates.');
        console.log('2022 Valid Pixels:', result2022.count);
        console.log('2019 Valid Pixels:', result2019.count);
        console.log('C2');
        return;
    }

    const waterPixels2022 = result2022.pixels;
    const waterPixels2019 = result2019.pixels;

    if (waterPixels2022 === null || waterPixels2019 === null) {
        console.log('Error: Calculation failed, result is null.');
        console.log('2022 Water Pixels:', waterPixels2022);
        console.log('2019 Water Pixels:', waterPixels2019);
        console.log('C3');
        return;
    }

    console.log(`2022 Water Pixels: ${waterPixels2022} (out of ${result2022.count} total)`);
    console.log(`2019 Water Pixels: ${waterPixels2019} (out of ${result2019.count} total)`);

    if (waterPixels2022 > waterPixels2019) {
        console.log('Conclusion: Water extent was greater in 2022.');
        console.log('A');
    } else {
        console.log('Conclusion: Water extent was not greater in 2022.');
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('Authentication or Initialization error:', e);
        console.log('D');
    }
}

initEE();
